53:// 里程碑清单的存放位置以写入类型表声明的为准，不另抄一份路径字面量（tick-begin 落指针、
54-// artifact add fallback 盖戳都要读它）。
55-const MILESTONES_REL = WRITE_TYPES['phase1-milestones'].path();
56-
57-// 带退出码的错误：业务代码抛它，CLI 收尾时按 exitCode 退出；不带退出码的错误一律按 EXIT.ERROR。
58-class CliError extends Error {
59-  constructor(message, exitCode = EXIT.ERROR) {
60-    super(message);
61-    this.exitCode = exitCode;
62-  }
63-}
64-
65-// 解析命令行：第一个不带 -- 的词是子命令，其余不带 -- 的词按顺序进 positionals；
66-// 「--名 值」进 flags；--名 后面直接跟另一个 --名（或到头了）就当开关记 true。
67-function parseArgs(argv) {
68-  const positionals = [];
69-  const flags = {};
70-  for (let i = 0; i < argv.length; i++) {
71-    const token = argv[i];
72-    if (token.startsWith('--')) {
73-      const name = token.slice(2);
74-      const next = argv[i + 1];
75-      if (next === undefined || next.startsWith('--')) {
76-        flags[name] = true;
77-      } else {
78-        flags[name] = next;
79-        i++;
80-      }
81-    } else {
82-      positionals.push(token);
83-    }
84-  }
85-  const [command, ...rest] = positionals;
86-  return { command, positionals: rest, flags };
87-}
88-
89-// —— write 的两个可复用零件：先校验、后落盘，单写与批量（write batch）共用 ——
90-
91-// 校验单笔写入：查写入类型表 → 校验 id（一名一档的类型必须给）→ 跑该类型校验器
92-//（tick-field 顺带过叙述校验器，坏叙述进不了草稿）。纯校验、不落盘；不合格抛 CliError。
93-// 返回 { def, id, rel } 供落盘用。idLabel 只改缺 id 时的白话措辞（单写说「--id」，批量说「id」）。
94-function validateOneWrite(type, data, rawId, idLabel = '--id') {
95-  const def = WRITE_TYPES[type];
96-  if (!def) {
97-    throw new CliError(`不认识的写入类型「${type}」，合法类型：${Object.keys(WRITE_TYPES).join('、')}`);
98-  }
99-  // path 函数声明了参数（一名一档的文件，如 sprints/<id>.json）就必须给 id。
100-  // 先解析 id 再跑校验器：有的类型（如 taste-example 的后缀白名单）要连名字一起校验。
101-  let id;
102-  if (def.path.length > 0) {
103-    if (typeof rawId !== 'string' || rawId.trim() === '') {
104-      throw new CliError(`写入类型「${type}」需要 ${idLabel} 指明写到哪一份文件`);
105-    }
106-    id = rawId;
107-    // 档案编号只是名字，不是路径——含路径符号一律拒收，防止用 ../ 逃出 .opc/ 容器。
108-    if (id.includes('/') || id.includes('\\') || id.includes('..')) {
109-      throw new CliError(`${idLabel}「${id}」含路径符号（/、\\ 或 ..），档案编号只能是纯名字`);
110-    }
111-  }
112-  def.validate(data, id); // 校验不过会抛白话错误，CLI 转 EXIT.ERROR
113-  // tick 叙述在提交这一步就过叙述校验器，坏叙述根本进不了草稿。
--
477:// tick-begin 子命令：一轮 tick 的开工三连——取锁（租约+代数）、序号入状态档、登记本会话派工。
478-// stdout 给出 {generation, tickSeq}；这一轮后续所有写类调用都必须带着这个代数（--gen）。
479-// 可选参数：--session 会话标识（记账归属靠它，见下方取值优先级）；--employee 登记成哪个员工
480-//          （默认「主控」）；--lease-ms 租约时长毫秒（默认 15 分钟）；--pid 持有者进程号
481-//          （默认本进程，带外的壳可传自己的常驻进程号，让探活盯对地方）。
482-//
483:// 会话标识取值优先级（E 项：会话标识机器盖章，tick-begin 不再只认自报值）：
484-//   ① SessionStart 钩子经 session-mark 盖的机器戳（runtime/current-session.json）——
485-//      真实、不可伪造，是记账归属的首选依据；
486-//   ② 没盖章（比如非 Claude Code 环境手工跑、钩子还没来得及跑）时退回显式 --session
487-//      （兼容旧写法，模型自报）；
488-//   ③ 两样都没有，退回「进程-<pid>」的兜底标识（老行为，非记账场景够用）。
489-// 机器戳和 --session 两样都有但对不上时，以机器戳为准，并在输出的 session_note 里注明——
490-// 不吞这个分歧，让带外调度器/审计能看见「模型报错了会话号」这件事本身。
491-async function cmdTickBegin({ root, flags }) {
492-  const reportedSession = typeof flags.session === 'string' && flags.session.trim() !== ''
493-    ? flags.session.trim()
494-    : null;
495-  const stamped = await readJson(root, RUNTIME_CURRENT_SESSION_PATH);
496-  const stampedSession =
497-    stamped !== null && typeof stamped.session_id === 'string' && stamped.session_id.trim() !== ''
498-      ? stamped.session_id.trim()
499-      : null;
500-
501-  let session;
502-  let sessionNote;
503-  if (stampedSession !== null) {
504-    session = stampedSession;
505-    if (reportedSession !== null && reportedSession !== stampedSession) {
506-      sessionNote =
507-        `--session 报的「${reportedSession}」与机器盖章「${stampedSession}」不一致，` +
508-        '以机器盖章为准（SessionStart 钩子经 session-mark 登记的才是真实会话标识）';
509-    }
510-  } else {
511-    session = reportedSession ?? `进程-${process.pid}`;
512-  }
513-
514-  const options = { session };
515-  if (flags['lease-ms'] !== undefined) {
516-    const leaseMs = Number(flags['lease-ms']);
517-    if (typeof flags['lease-ms'] !== 'string' || !Number.isInteger(leaseMs) || leaseMs <= 0) {
518-      throw new CliError('--lease-ms 需要带一个正整数（毫秒）');
519-    }
520-    options.leaseMs = leaseMs;
521-  }
522-  if (flags.pid !== undefined) {
523-    const pid = Number(flags.pid);
524-    if (typeof flags.pid !== 'string' || !Number.isInteger(pid) || pid <= 0) {
525-      throw new CliError('--pid 需要带一个正整数（进程号）');
526-    }
527-    options.pid = pid;
528-  }
529-
530-  const got = await acquire(root, options);
531-  if (!got.acquired) {
532-    const h = got.holder;
533-    // holder 可能是 null：极端竞争下刚输给别人、对方又立刻放了锁，此时只知道自己没抢到。
534-    const who = h
535-      ? `第 ${h.generation} 代持有者还活着且租约未到期` +
536-        `（进程 ${h.holder?.pid ?? '不明'}，会话 ${h.holder?.session ?? '不明'}，租约到 ${h.lease_expires_at}）`
537-      : '刚被别的会话抢走';
538-    throw new CliError(`锁被占着：${who}`, EXIT.LOCK_HELD);
539-  }
540-
541-  // 序号在取锁时已分配并写进锁文件，这里让状态档跟上（经 store，有指纹有事件）。
542-  const state = await readJson(root, PATHS.state);
543-  if (state === null) {
--
549:    event: `tick-begin:第 ${got.tickSeq} 轮（第 ${got.generation} 代）`
550-  });
551-
552-  // 机器闸：本轮该主攻哪个里程碑、指针要不要新立，由脚本在开工时当场落定——不指望 AI 记得跑
553-  // activate-milestone（precheck 附的文字指令保留但正确性不再靠它）。这样同一轮后续 artifact add
554-  // 必然读得到 active_milestone、盖上里程碑戳。选取逻辑与 precheck 同源（pickMainMilestone）：
555-  // 指针已指向未收官里程碑则 activate 为 undefined、绝不覆盖；空缺或指着已收官的才新立。
556-  const milestones = await readJson(root, MILESTONES_REL);
557-  if (Array.isArray(milestones)) {
558-    const { activate } = pickMainMilestone(milestones, state);
559-    if (activate !== undefined) {
560-      // activateMilestone 自带「只认 planned/failed」校验，pickMainMilestone 选出的正是这两种，稳过。
561-      await activateMilestone(root, activate, { actor: '脚本' });
562-    }
563-  }
564-
565-  // 登记本会话的派工：员工↔会话映射进账本，记账归属靠它。格式以写入类型表为准。
566-  const employee = typeof flags.employee === 'string' && flags.employee.trim() !== '' ? flags.employee : '主控';
567-  const dispatch = { session_id: session, employee, tick: got.tickSeq };
568-  WRITE_TYPES['dispatch'].validate(dispatch);
