file.content:
// 这类探查会真去取锁——未带 --session/--pid 时持有者是瞬死的 opc.mjs 子进程，造出「持有者立即
// 死亡」的幽灵代次、给幽灵轮写 status=aborted 的 tick 文件，污染账本。此闸从根上堵住这条探查副作用。
// 注：parseArgs 只把 `--` 前缀当 flag，`-h` 会落进 positionals、不进 flags.help；本闸只认 --help。
if (flags.help === true) {
  process.stdout.write(
    `用法：node scripts/opc.mjs ${command} [--dir 项目根] [--json '<数据>'] [--id x] [--gen n] …\n` +
      `（--help 只打印本行、不执行任何动作；子命令「${command}」的具体参数见剧本或 scripts/opc.mjs 源码。）\n`
  );
  return EXIT.OK;
}
// 项目根解析优先级：显式 --dir > OPC_PROJECT_DIR 环境变量 > process.cwd() 兜底。
// 中间那道是给「靠 cwd 认项目根」的场景兜底：tick 壳剧本用 `${CLAUDE_PLUGIN_ROOT}/scripts/opc.mjs`
// 定位脚本、不带 --dir，模型有时会 cd 到插件目录再跑，cwd 一变就找错项目根（退 20）。
// 控制台起会话时把项目根塞进 OPC_PROJECT_DIR，认它优先于 cwd，模型 cd 到哪都不影响——
// 从根上消掉「靠模型守住 cwd」这条劝导，不是靠提示词。
const envDir = process.env.OPC_PROJECT_DIR;
const root =
  typeof flags.dir === 'string' && flags.dir !== ''
    ? flags.dir
    : typeof envDir === 'string' && envDir.trim() !== ''
      ? envDir
      : process.cwd();

// 不需要项目就能跑的子命令：scaffold（它就是来建 .opc/ 的）、format-doc
// （它说明的是插件自己的契约）、team（它管的是插件源码 teams/，跟 .opc/ 无关）、
// exam（同 team，管的是 teams/ 下的成绩单，跟某个项目的 .opc/ 无关）。
// 这几个对「找 .opc/」、版本预检和代数围栏都豁免；其余子命令一律先过这几关。
const PROJECTLESS_COMMANDS = new Set(['scaffold', 'format-doc', 'team', 'exam']);
let migration = null;
// 带外收尾接管（bug3）：无 --gen 的写类命令撞上「僵尸锁」（持有者进程已死）时，经 acquire 原子接管

