12-import { listArtifacts } from './artifact.mjs';
13-
14-// 里程碑清单的存放位置以写入类型表声明的为准，不另抄一份路径字面量。
15-const MILESTONES_REL = WRITE_TYPES['phase1-milestones'].path();
16-// 品味 demo 的存放目录（从写入类型表推出，不另抄字面量）。
17-const TASTE_EXAMPLES_REL = path.posix.dirname(WRITE_TYPES['taste-example'].path('占位.html'));
18-
19-// 品味是否留过能看的真实 demo：examples/ 下有认得后缀的例子文件。
20-async function hasTasteDemoFile(root) {
21-  const names = await listOpcDir(root, TASTE_EXAMPLES_REL);
22-  return names.some((n) => Object.keys(TASTE_EXAMPLE_KINDS).some((s) => n.endsWith(s)));
23-}
24-
25-// 品味 demo 是否登记进了画廊 manifest（source=taste/*）。2026-07-16 收紧（老板拍板）：
26-// 光有文件不够——老板只经 hub 画廊/Preview 看 demo，manifest 没条目＝老板从没看见过它。
27-// 走 write taste-example 通道落盘会自动登记（opc.mjs text 分支）；绕通道直接写文件、或
