43:function assertTransition(kind, from, to) {
44:  const table = TRANSITIONS[kind];
45-  const targets = table[from];
46-  if (!Array.isArray(targets) || !targets.includes(to)) {
47-    throw new IllegalTransition(`${kind} 不允许从「${from}」流转到「${to}」`);
48-  }
49-}
50-
51-// 读 state.json，不存在就报错——它是模板自带的底档，缺了说明项目坏了。
52-async function readState(root) {
53-  const state = await readJson(root, PATHS.state);
54-  if (state === null) {
55-    throw new Error(`找不到 ${PATHS.state}，项目状态档缺失，没法推状态`);
56-  }
57-  return state;
58-}
59-
