63-export async function advance(root, kind, id, toState, { actor } = {}) {
64-  if (typeof actor !== 'string' || actor.trim() === '') {
65-    throw new Error('advance 必须注明 actor（这次是谁在推状态）');
66-  }
67-  switch (kind) {
68-    case 'project':
69-      return advanceProject(root, toState, actor);
70-    case 'milestone':
71-      return advanceMilestone(root, id, toState, actor);
72-    case 'sprint':
73-      return advanceSprint(root, id, toState, actor);
74-    case 'tick':
--
86-  const state = await readState(root);
87-  const from = state.phase;
88:  assertTransition('project', from, toState);
89-  if (from === 'phase1' && toState === 'phase2') {
90-    const signoffRel = WRITE_TYPES['phase1-signoff'].path();
91-    const signoff = await readJson(root, signoffRel);
92-    if (signoff === null) {
93-      throw new Error(`阶段一还没签字（缺 ${signoffRel}），不许进阶段二`);
94-    }
95-    // 品味必须留过能看的真实 demo（examples/ 下至少一个文件）——文字描述不了老板心里想要的，
96-    // 得有 demo 让老板确认过。判定归脚本，不靠嘴上「必须」。
97-    if (!(await hasTasteDemoFile(root))) {
98-      throw new Error(
99-        '阶段一还没留品味 demo（phase1/taste/examples/ 下一个文件都没有），不许进阶段二——' +
100-          '先 write taste-example 造个能看的 demo 让老板确认'
101-      );
102-    }
103-    // 且 demo 必须已登记进画廊 manifest（2026-07-16 收紧，老板拍板）：老板只经 hub 看 demo，
104-    // 没登记＝没给老板看过。正常走 write taste-example 通道两者必然同时成立；这里拦的是
105-    // 「文件在、条目缺」的绕道/登记失败残局。
106-    if (!(await hasTasteDemoRegistered(root))) {
107-      throw new Error(
108-        '品味 demo 文件在 phase1/taste/examples/ 里，但画廊登记册（artifacts/manifest.json）没有' +
109-          ' source=taste/* 的条目——老板在 hub 里看不见它，不许进阶段二。用 write taste-example' +
110-          ' 以同一个 --id 重新落盘一次即可补登记（同 id 幂等，原文重写不丢内容）'

